<script lang="ts">import{onMount}from'svelte';import type{EditorStore}from'../store.js';import{patchElement,updateDocument}from'../commands.js';import{parseCsv}from'../template/csv.js';import{evaluateTemplate}from'../template/evaluate.js';import{EditorDatabase}from'../persistence/database.js';import type{TemplateData}from'../model.js';export let editor:EditorStore;const database=new EditorDatabase();let error='';let templates:{key:IDBValidKey,value:TemplateData}[]=[];onMount(refresh);async function refresh(){templates=await database.entries<TemplateData>('templates')}async function load(event:Event){try{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;const parsed=parseCsv(await file.text());const template={...parsed,currentRecord:0};editor.execute(updateDocument({template}));await database.saveTemplate($editor.document.id,template);await database.saveRecent({id:$editor.document.id,kind:'template',openedAt:new Date().toISOString()});await refresh();error=''}catch(reason){error=reason instanceof Error?reason.message:String(reason)}}
function record(index:number){const template=$editor.document.template;if(template)editor.execute(updateDocument({template:{...template,currentRecord:index}}))}
function map(element:import('../model.js').TextElement|import('../model.js').BarcodeElement|import('../model.js').QrElement,field:string,transform=''){if(field){const value=`{{${field}${transform?`|${transform}`:''}}}`;editor.execute(patchElement(element.id,element.type==='text'?{text:value}:{value}))}}
</script>
<section><h2>Data & templates</h2><label class="upload">Import CSV<input type="file" accept=".csv,text/csv" on:change={load}></label>{#if templates.length}<label>Saved data template<select on:change={e=>{const item=templates[+e.currentTarget.value];if(item)editor.execute(updateDocument({template:structuredClone(item.value)}))}}><option value="">Choose saved template</option>{#each templates as item,index}<option value={index}>{String(item.key)} · {item.value.records.length} records</option>{/each}</select></label>{/if}{#if error}<p class="error">{error}</p>{/if}{#if $editor.document.template}{@const template=$editor.document.template}<p>{template.records.length} records · {template.fields.join(', ')}</p><label>Preview record <input type="range" min="0" max={Math.max(0,template.records.length-1)} value={template.currentRecord} on:input={(e)=>record(+e.currentTarget.value)}></label><dl>{#each template.fields as field}<dt>{field}</dt><dd>{template.records[template.currentRecord]?.[field]??''}</dd>{/each}</dl><h3>Explicit field mapping</h3>{#each $editor.document.elements.filter(e=>e.type==='text'||e.type==='barcode'||e.type==='qr') as element}<div class="mapping"><label>{element.name}<select class="field"><option value="">Choose CSV field</option>{#each template.fields as field}<option value={field}>{field}</option>{/each}</select></label><label>Transform<select on:change={e=>map(element,(e.currentTarget.closest('.mapping')?.querySelector('.field') as HTMLSelectElement)?.value,e.currentTarget.value)}><option value="">None</option><option>upper</option><option>lower</option><option>trim</option><option>ascii</option><option value="number:2">number (2 decimals)</option><option value="date:%Y-%m-%d">date YYYY-MM-DD</option></select></label></div>{/each}<h3>Resolved elements</h3><ul>{#each $editor.document.elements.filter(e=>e.type==='text'||e.type==='barcode'||e.type==='qr') as element}<li>{element.name}: {evaluateTemplate(element.type==='text'?element.text:element.value,{record:template.records[template.currentRecord]??{}})}</li>{/each}</ul>{/if}</section>
<style>section{padding:.75rem;border-top:1px solid #ddd}h2{font-size:.8rem;text-transform:uppercase}.upload{display:inline-block;border:1px solid #bbb;padding:.35rem;border-radius:4px}.upload input{position:absolute;opacity:0;width:1px}dl,.mapping{display:grid;grid-template-columns:1fr 1fr;font-size:.75rem;gap:.3rem}dt,dd{margin:0;padding:.15rem}.error{color:#a21}</style>
